#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# ──────────────────────────────────────────────────────────────────────────

# The Lobby's invite emails (#101, ADR 0014) go out through
# Fastmail SMTP with an app password. This wizard makes that app password
# with you and stores it, with your Fastmail sign-in address, as SecureStrings
# the site reads: /the-lobby/dev/smtp/{username,password} and
# /the-lobby/prod/smtp/{username,password}. Only the sign-in address is
# remembered between runs; the password is never written to disk.

TOTAL_STAGES=4
ENV_FILE="$HOME/.the-lobby-invite-wizard.env"
PROFILE=workloads-admin
REGION=us-west-2
ACCOUNT=793680745829
FROM=lobby@craigdevjohnson.com

# put_param NAME VALUE writes one SecureString with the account's aws/ssm key.
put_param() {
  aws ssm put-parameter --profile "$PROFILE" --region "$REGION" \
    --name "$1" --type SecureString --overwrite --value "$2" >/dev/null
  printf '  %s✓ saved%s %s\n' "$GREEN" "$RESET" "$1"
}

banner "The Lobby: invite emails through Fastmail"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Check the tools and your AWS sign-in"
for tool in aws curl; do
  if ! command -v "$tool" >/dev/null 2>&1; then
    warn "$tool isn't installed. Install it (brew install awscli curl), then run this again."
    exit 1
  fi
done
if ! aws sts get-caller-identity --profile "$PROFILE" >/dev/null 2>&1; then
  say "Signing you in to AWS as $PROFILE. A browser page opens; approve it."
  aws sso login --profile "$PROFILE"
fi
account=$(aws sts get-caller-identity --profile "$PROFILE" --query Account --output text)
if [[ "$account" != "$ACCOUNT" ]]; then
  warn "$PROFILE is signed in to account $account, not $ACCOUNT. Stopping."
  exit 1
fi
say "${GREEN}✓${RESET} Signed in to AWS account $ACCOUNT as $PROFILE."
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Fastmail: make an app password for The Lobby"
say "The site signs in to Fastmail with its own app password, never your account password."
open_url "https://app.fastmail.com/settings/security"
step "In Settings › Privacy & Security, find Connected apps & API tokens and click Manage app passwords and access."
step "Click New app password. Name it: The Lobby invites"
step "For access, pick SMTP only if it is offered (it may sit under Custom). Otherwise pick Mail (IMAP/POP/SMTP)."
step "Fastmail shows the password once. Copy it."
ask_secret SMTP_PASSWORD "Paste the app password (hidden):"
SMTP_PASSWORD="${SMTP_PASSWORD// /}"   # Fastmail shows it in groups; spaces aren't part of it
if [[ -z "$SMTP_PASSWORD" ]]; then
  warn "No password was pasted. Run the wizard again when you have it."
  exit 1
fi
say ""
say "SMTP signs in with the address you use to sign in to Fastmail."
ask SMTP_USERNAME "Your Fastmail sign-in address:"
if [[ "$SMTP_USERNAME" != *@*.* ]]; then
  warn "That doesn't look like an email address. Run the wizard again."
  exit 1
fi
write_env SMTP_USERNAME "$SMTP_USERNAME"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Check the password works: send yourself a test email"
say "This signs in to smtp.fastmail.com:465 as $SMTP_USERNAME and sends one email"
say "from $FROM to $FROM, which lands in your Fastmail inbox."
netrc=$(mktemp)
msg=$(mktemp)
trap 'rm -f "$netrc" "$msg"' EXIT
chmod 600 "$netrc"
printf 'machine smtp.fastmail.com login %s password %s\n' "$SMTP_USERNAME" "$SMTP_PASSWORD" > "$netrc"
printf 'From: The Lobby <%s>\r\nTo: %s\r\nSubject: The Lobby can send invite emails\r\n\r\nThis is the invite wizard checking the app password. You can delete it.\r\n' "$FROM" "$FROM" > "$msg"
if curl -sS --max-time 30 --ssl-reqd --url "smtps://smtp.fastmail.com:465" --netrc-file "$netrc" \
  --mail-from "$FROM" --mail-rcpt "$FROM" --upload-file "$msg"; then
  say "${GREEN}✓${RESET} Fastmail took the test email. Look for \"The Lobby can send invite emails\" in your inbox."
else
  warn "Fastmail refused it. Check the sign-in address and that the app password allows SMTP, then run this again."
  exit 1
fi
rm -f "$netrc" "$msg"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Store it for dev and production"
say "This writes four SecureStrings in AWS (account $ACCOUNT, $REGION):"
note "  /the-lobby/dev/smtp/username   /the-lobby/dev/smtp/password"
note "  /the-lobby/prod/smtp/username  /the-lobby/prod/smtp/password"
if confirm "Write them now?"; then
  for env in dev prod; do
    put_param "/the-lobby/$env/smtp/username" "$SMTP_USERNAME"
    put_param "/the-lobby/$env/smtp/password" "$SMTP_PASSWORD"
  done
  missing=$(aws ssm get-parameters --profile "$PROFILE" --region "$REGION" \
    --names /the-lobby/dev/smtp/username /the-lobby/dev/smtp/password \
            /the-lobby/prod/smtp/username /the-lobby/prod/smtp/password \
    --query 'InvalidParameters' --output text)
  if [[ -z "$missing" || "$missing" == "None" ]]; then
    say "${GREEN}✓${RESET} All four are there. The next Add Member on Lobby Admin sends the invite."
  else
    warn "Not found after writing: $missing"
    SKIPPED+=("SecureStrings: $missing")
  fi
else
  SKIPPED+=("the four SecureStrings under /the-lobby/{dev,prod}/smtp/ (run this wizard again)")
fi
unset SMTP_PASSWORD
pause "Press Enter to finish"

finish
